    secureGatewayDesc: "تُشفَّر كل بيانات الدفع وتُعالَج بأمان عبر Stripe، ولا يمكننا الوصول إلى معلوماتك الحساسة أو بيانات بطاقتك أو تخزينها، ما يمنحك راحة بال تامة.",
    importantNotice: "إشعار مهم",
    tokenDisclaimer: "تعمل رموز DeHub كرموز منفعة داخل نظامنا البيئي، مشابهة للعملات داخل الألعاب، وليست أدوات استثمارية. ومع أن بنيتنا التحتية على البلوكتشين توفر شفافية غير مسبوقة وبيانات قابلة للتحقق على السلسلة لأغراض تعليمية، فإن كل الأسواق تحمل مخاطر متأصلة. وقد تخسر استثمارك بالكامل بسبب تقلبات السوق أو مشكلات تقنية أو خروقات أمنية أو ظروف غير متوقعة. شارك فقط بأموال تستطيع تحمّل خسارتها كلياً. ولا تتحمل DeHub وشركاؤها أي مسؤولية عن أي خسائر مالية.",
    exploreTitle: "استكشف التطبيق وما بعده",
