    exploreFormula: "وهذه معاً تحدد حصة عائدات الإعلانات (RS). والخوارزمية الدقيقة لذلك في مرحلة تجريبية وقابلة للتغيير بحسب العائد المتحقق (RG)",
    exploreAlgorithm: "هذه هي الخوارزمية الأساسية، وستستمر التجارب في المكافآت بأسلوب المحاولة والخطأ حتى يُبلغ التوازن الأمثل.",
    badgeTitle: "استعرض شارتك",
    badgeSubtitle: "نموذج شارة الشرف",
    badgeDesc: "كلما زاد عدد رموز DeHub التي تحملها، زادت مكافأتها، بهذه البساطة. ويشمل ذلك على سبيل المثال لا الحصر نظام شارة الشرف الذي يفتح مستحضرات التجميل المحسنة على ملفك الشخصي العام بالإضافة إلى المزيد من الميزات المحسنة والمتميزة.",
    badgePriceTitle: "السلّم مسعّر بالدولار",
    badgePriceDesc: "المستويات الثلاثة عشر، السلطعون من خلال الميجالودون، كل منها يكلف مبلغًا ثابتًا بالدولار بدلاً من عدد ثابت من الرموز. عدد رموز DeHub التي يطلبها المستوى هو أن تكلفة الدولار بالسعر الفعلي، لذلك فإن الشارة تعني نفس الالتزام مهما كان ما يفعله السوق. يأتي معها نوعان من الحماية: الشرط لا يرتفع أبدًا عن الأرقام المنشورة إذا انخفض السعر، وبمجرد وصولك إلى مستوى تحتفظ به — الشارة التي ربحتها مؤمنة بأرخص شرط حصلت عليه على الإطلاق، لذلك لا يمكن للهبوط أن يجردك منه.",
    badgeUnlockTitle: "ماذا تفتح الشارة",
    badgeUnlock1: "رسوم أقل على الإكراميات والدفع لكل مشاهدة والاشتراكات والمكافآت، تنخفض 0.69% لكل مستوى.",
    badgeUnlock2: "حصة نشر يومية مجانية أكبر، وخصم على ما يتجاوزها.",
    badgeUnlock3: "نفس الخصم عند شراء رموز DeHub، من 5 ٪ في Crab إلى 30 ٪ في Megalodon.",
    badgeUnlock5: "وزن أكبر لما تفعله: المشاهدة أو التفاعل من حامل شارة يُحتسب أكثر، على السلّم نفسه المستخدم في تصويت الحوكمة — واحد بلا شارة، واثنان عند السرطان، ودرجة إضافية لكل مستوى أعلى حتى أربعة عشر عند الميغالودون. إنه مضاعف على تفاعلك الواحد، وليس تفاعلاً ثانياً أبداً.",
    badgeDelegationTitle: "أعِر شارتك",
    badgeDelegationDesc: "يمكن إعارة الشارة. فكل درجة صعدتها تمنحك خانة تفويض واحدة — واحدة عند السرطان وثلاث عشرة عند الميغالودون — وكل خانة تمنح حساباً آخر مستواك ما دمت تتركها هناك. وهي موجودة لأن النفوذ في DeHub مصمم ليتنقل مع مجموعة لا أن يستقر في محفظة واحدة: الأطقم والفرق والحسابات الثانية تحصل على مستوى داعمها، دون أن ينقل أحد رموزاً أو يسلّم مفاتيح.",
    badgeDelegationB1: "المستوى نفسه، لا الذي دونه:",
