    badgeDelegationB2: "الخانات تأتي من رهنك أنت:",
    badgeDelegationB2Desc: "الشارة المعارة لا تحمل خانات خاصة بها، فلا يمكن إعادة إعارة مستوى معار.",
    badgeDelegationB3: "الراعي معلن:",
    badgeDelegationB3Desc: "مرّر المؤشر فوق شارة مفوّضة في أي مكان في التطبيق فتظهر لك من يدعمها. لا شيء مخفي عن مصدر المستوى.",
    badgeDelegationB4: "قابلة للاسترجاع في أي وقت:",
    badgeDelegationB4Desc: "استرجع خانة فيعود المستوى إليك. ولا يتأثر رهنك ومستوى رسومك وشارتك المقفلة بأي شيء تعيره.",
    badgeDelegationB5: "مكانة، لا استحقاقات:",
    badgeDelegationB5Desc: "الشارة المعارة هي ما تعرضه المنصة، وتحمل الوزن الذي يتناسب مع الطبقة — يتم احتساب المنظر أو رد الفعل منه في الطبقة التي تم إقراضها بها. ما لا يحمله هو أي شيء يتم تسعيره بالمال: مستوى الرسوم الخاص بك، وخصم شراء الرمز المميز الخاص بك، وبدل النشر اليومي الخاص بك، وفتحات التفويض الخاصة بك كلها لا تزال تقرأ من الحصة التي تحملها بنفسك.",
    badgeDelegationB6: "قم بإعارة أي درجة قمت بتسلقها:",
