    badgeDelegationB7: "والجانب الآخر له رأي:",
    badgeDelegationB7Desc: "تظهر شارة معروضة على حساب في جرس الإشعارات الخاص به، ويمكنه رفضها. يمكن لأي منكما إنهاء التفويض بعد ذلك.",
