    commUser5: "تكامل سلس مع ميزات Web3",
    superPowersTitle: "القوى الخارقة",
    superPowersDesc: "تحوّل القوى الخارقة شارة الرهن إلى وصول يمكنك إنفاقه. كل أسبوعين تمنحك شارتك دفعات تعزيز، وإنفاق واحدة يضع منشوراً في الخانة أعلى التغذية الرئيسية. ثلاثة عشر مستوى، وثلاث عشرة قوة، وفتح واحد لكل درجة — فالدرجة التالية تشتري دائماً شيئاً جديداً واحداً بالضبط. والخانة تتناوب: حين تعمل عدة تعزيزات، يُعرض للمشاهدين واحد مرجّح بمستوى الشارة، فيظهر المستوى الأعلى أكثر ويحصل الجميع مع ذلك على النافذة الممنوحة لهم.",
    boostPower: "1) التعزيز",
    boostPowerDesc: "ضع منشوراً من الأسبوع الماضي في أعلى التغذية الرئيسية. يُفتح عند السرطان. متاح الآن.",
    secondWindPower: "2) النفَس الثاني",
    secondWindPowerDesc: "أعِد منشوراً أقدم من أسبوع إلى أعلى التغذية. يُفتح عند الكركند. متاح الآن.",
    trendJacker: "4) خاطف الرائج",
    trendJackerDesc2: "ضع إحدى فئاتك في أعلى قائمة الرائج. يُفتح عند السلحفاة العملاقة. متاح الآن.",
    timelineBomber: "5) قاصف المخطط الزمني",
    timelineBomberDesc2: "يرى متابعوك منشورك قبل تعزيز أي شخص آخر — فالكوبرا الملكية يتغلب على الميغالودون لدى من اختاروا متابعتك. يُفتح عند الكوبرا الملكية. متاح الآن.",
    precisionStrike: "8) الضربة الدقيقة",
    precisionStrikeDesc: "صِل إلى متابعي حساب تحدده. يُفتح عند الدلفين. متاح الآن.",
    harpoon: "9) الحربة",
    harpoonDesc: "صِل إلى مستويات شارات مختارة فقط — الحيتان أو القروش أو كل من دونها. يُفتح عند قرش النمر. متاح الآن.",
    superPowersMore2: "الدرجات الثلاث عشرة كلها متاحة، ومدرجة في التطبيق مع المستوى الذي تُفتح عنده كل منها. مرساة التعليق تُبقي تعليقك في أعلى موضوع شخص آخر. الشهاب المضيء يرسل إشعاراً واحداً إلى كل حساب يتابعك. سترة الشظايا تجعل المنشور محصناً من الدفن بالتصويت السلبي طوال عملها. الساعة الذهبية تضاعف رصيد الترتيب لكل ما تنشره خلالها بشكل دائم. تعزيز الطاقم يفتح تعزيزاً يستطيع حاملو شارات آخرون الانضمام إليه، كل بدقائقه. الصف الأول يضع المسرح الذي تستضيفه في أعلى شريط المسارح. التيار العميق يمنح أحد تعزيزاتك لمنشور شخص آخر.",
    superPowersLink: "اطّلع على حصتك وعلى السلّم كاملاً",
