    spRotationDesc: "تدور الفتحة بدلاً من الدبابيس. عندما تعمل عدة تعزيزات في نفس الوقت، يتم منح كل مشاهد واحداً، مرجحاً حسب مستوى شارة المعزز — يتم عرض المستوى الأعلى بشكل متكرر أكثر، وكل شخص لا يزال يحصل على النافذة التي دفع ثمنها. ما يشتريه التعزيز هو حصة من الصوت لعدد محدد من الدقائق، وليس الحيازة الحصرية لأعلى الخلاصة.",
