    affected3: "توزيعات المكافآت",
    affected4: "مدفوعات الاشتراكات",
    affected5: "تداول عمليات الرفع المرمّزة",
    exampleSavings: "مثال على التوفير",
    feeDisclaimer: "إشعار مهم بشأن الرسوم",
    feeDisclaimerDesc: "لا تنطبق الرسوم إلا على خدمات معينة مثل الإكراميات والاشتراكات والدفع لكل مشاهدة ومكافآت المشاهدة مقابل الربح. ويستطيع المستخدمون إرسال الرموز إلى بعضهم مجاناً في أنحاء التطبيق واستخدام أدوات التجريد لدينا للقيام بذلك دون الحاجة إلى عنوان محفظة أو إدارة مفاتيح خاصة.",
    tocTitle: "في هذه الصفحة",
    tocIntro: "البداية",
    tocAccounts: "الحسابات",
    tocFeeds: "التغذيات",
    tocUploading: "الرفع",
    tocTokenised: "عمليات الرفع المرمّزة",
