    intro: "رموز DeHub هي عملة المنفعة الأصلية لشبكة DeHub ؛ DHB هو رمز المؤشر الخاص بهم. إنها وحدة الحساب الوحيدة عبر كل تطبيق - الشيء الذي تقدم به الإكرامية، وتفتح المحتوى به، وتكسبه من المشاهدة والإبداع، وتنفقه على توليد الذكاء الاصطناعي. نظرًا لأنهم يعيشون على السلسلة، فإن كل حركة ذات قيمة في النظام البيئي يمكن التحقق منها علنًا بدلاً من الجلوس في دفتر أستاذ خاص عليك أن تأخذ كلمتنا من أجله.",
    howItWorksTitle: "كيف تعمل العملة داخل التطبيق",
    howItWorksDesc1: "يحتوي كل حساب على DeHub على محفظة مدمجة. يمكنك تمويلها ببطاقة من خلال بوابة Stripe الخاصة بنا، أو استلامها من مستخدم آخر، أو كسبها من المنصة، أو إيداعها من أي محفظة ذاتية الحفظ — لا يوجد تطبيق منفصل أو ملحق أو عبارة أولية مطلوبة للبدء. يتم تسوية جميع الأرصدة والإكراميات وإلغاء القفل والمكافآت في رموز DeHub، لذلك تنتقل القيمة بين المستخدمين مباشرة بدلاً من توجيهها من خلال معالج دفع يأخذ قسطًا ويمكنه تجميد الحساب.",
