    useFeesTitle: "الرسوم والرهن والحوكمة",
    useFeesDesc: "دفع رسوم الشبكة، والمشاركة في مستويات النادي لحصة إيرادات البروتوكول، وحرق رموز DeHub للإدلاء بأصوات الحوكمة على قرارات البروتوكول.",
    profitShareTitle: "مشاركة الأرباح",
    profitShareDesc1: "تم تصميم DeHub بحيث يمتلكها الأشخاص الذين يستخدمون الشبكة. تتدفق إيرادات البروتوكول — رسوم المنصة، ورسوم المتجر والسوق، والإعلان، واستخدام الذكاء الاصطناعي وإيرادات الألعاب — مرة أخرى إلى أصحاب الأسهم، في شكل توزيعات ذات عائد حقيقي وإعادة شراء بدلاً من التوريد الطازج. وبالتالي فإن امتلاك رموز DeHub هو ملكية حصة من شبكة DeHub نفسها، وليس مجرد رصيد إنفاق.",
    profitShareDesc2: "تُموَّل التوزيعات مما يكسبه البروتوكول فعلاً، على فترات متغيرة، وتُقسَّم على مستويات الرهن بحسب المبلغ ومدة الرهن معاً. فالالتزام الأطول يكسب حصة أكبر من كل توزيع. راجع الرهن للاطلاع على آليات المستويات وحساب المكافأة الدقيق.",
    pegTitle: "السعر المربوط والإدراج على منصات التداول اللامركزية",
    pegDesc1: "رمز DeHub هو رمز الأداة المساعدة. لأغراض داخل التطبيق، يتم ربطه حاليًا بمبلغ 0.001 $ لكل رمز، وهو السعر الذي تراه عند الشراء من خلال بوابة العملات الورقية والسعر المستخدم للتسعير داخل التطبيق. يوجد هذا الربط للحفاظ على الاقتصاد داخل التطبيق مستقرًا ويمكن التنبؤ به أثناء توسيع نطاق الشبكة — إنه معدل محاسبة داخلي، وليس حدًا أدنى أو ضمانًا أو وعدًا بقيمة مستقبلية.",
    pegDesc2: "يتم تداول الرمز المميز في البورصات اللامركزية، مع تجمعات السيولة المصنفة من نفس السعر الأساسي 0.001 عبر سلاسل متعددة. في السوق المفتوحة، يتم تحديد السعر عن طريق التداول — وليس عن طريق DeHub — مما يعني أن رموز DeHub يمكنها التداول أعلى أو أقل من الربط داخل التطبيق في أي وقت. تبذر DeHub سيولتها الرسمية على DEXs بحيث تظل كل معاملة قابلة للتحقق منها علنًا على السلسلة.",
    disclaimer: "إخلاء مسؤولية",
    disclaimerNoApy: "هام: في حين أن الاحتفاظ برموز DeHub يمنح الملكية في شبكة DeHub ويخول أصحاب المصلحة حصة من أرباح البروتوكول، لا يوجد APY محدد، ولا معدل عائد مضمون ولا توقع للربح من أي نوع. تعتمد جميع التوزيعات اعتمادًا كليًا على أداء الشبكة والإيرادات التي يحققها البروتوكول فعليًا في فترة معينة. قد تكون المكافآت أقل من أي فترة سابقة، وقد تكون صفرًا. لا شيء في هذه الصفحة هو وعد أو إسقاط أو عرض عائد، ولا شيء هنا هو نصيحة مالية.",
    disclaimerText: "رموز DeHub لأغراض المنفعة حصراً، شأنها شأن أي رموز أو عملات رقمية داخل الألعاب أو التطبيقات، وليست استثماراً على الإطلاق. ولأن رمزنا يعيش على السلسلة، نستطيع تقديم منفعة إضافية ومستويات غير مسبوقة من الشفافية القابلة للتحقق. والبيانات أعلاه جُمعت لأغراض الشفافية والتعليم والإعلام فقط. ولا تتحمل DeHub وكل شركائها أي مسؤولية عن خسائر مالية ناتجة عن شراء أي رموز أو رموز غير قابلة للاستبدال نصدرها. والأسواق شديدة التقلب. وقد تخسر كل أموالك أيضاً بسبب أخطاء غير متوقعة مثل إخفاقات الكفاءة أو الأخطاء التقنية أو الاختراقات وما إلى ذلك. ولذلك ينبغي ألا تنفق إلا ما تستطيع تحمل خسارته.",
