    walletConnections: "ربط المحافظ والهوية",
    walletText1: "يمكنك استخدام أجزاء من الخدمة، مثل تصفح المحتوى واكتشافه، دون ربط محفظة. لكنك تحتاج إلى محفظة تشفير متوافقة لاستخدام ميزات تحقيق الدخل والمشاركة في الحوكمة.",
    walletText2: "إنشاء المحتوى والمشاركة في اقتصاد المنصة يتطلبان ربط محفظة. وأنت مسؤول بالكامل عن:",
