    step3Title: "إنشاء منشورك الأول",
    step3Desc: "انقر على إنشاء. اكتب منشورًا، أضف صورًا، فيديو أو صوت، انتقل إلى \"مقال\" للكتابة الطويلة، أو اذهب مباشرة إلى بث حي. المنشور مجاني حتى حد يومي — عشرة منشورات نصية وغيغابايت من الوسائط يوميًا دون سمة (badge). صك المنشور على السلسلة (on-chain) اختياري ويمكن القيام به لاحقًا.",
